def _agregar_trio_urgencias(catalogo, familia, titulo, diagnostico, busqueda, escenarios):
    """Registra tres escenarios docentes completos para una misma familia clínica."""
    for conducta, datos in escenarios.items():
        estado = datos.pop("estado")
        examen_kwargs = datos.pop("examen_kwargs", {})
        catalogo[f"{familia} - {conducta.lower()}"] = _caso(
            nombre=f"{titulo} - {conducta.title()}",
            diagnostico=datos.pop("diagnostico", diagnostico),
            busqueda=datos.pop("busqueda", busqueda),
            conducta=conducta,
            examen=_examen_pediatrico_completo(estado, **examen_kwargs),
            familia=familia,
            aiepi="INTEGRAL",
            aiepi_criterios={
                "SIGNOS GENERALES DE PELIGRO Y ESTADO GENERAL": datos.pop("aiepi_estado", "SE DOCUMENTAN SIGNOS GENERALES DE PELIGRO, ESTADO GENERAL Y RESPUESTA CLÍNICA."),
                "ALIMENTACIÓN, HIDRATACIÓN Y DIURESIS": datos.pop("aiepi_ingesta", "SE DOCUMENTAN TOLERANCIA ORAL, HIDRATACIÓN Y DIURESIS SEGÚN CORRESPONDA."),
                "SIGNOS DE ALARMA, CONTROL Y RECONSULTA": datos.pop("aiepi_control", "SE BRINDA INFORMACIÓN A PADRES O CUIDADOR RESPONSABLE SOBRE LA CONDUCTA, SIGNOS DE ALARMA Y RECONSULTA."),
            },
            **datos,
        )


def _agregar_trio_clinico(catalogo, familia, titulo, diagnostico, busqueda, escenarios):
    """Crea variantes docentes completas con valores fisiológicos editables."""
    signos_por_conducta = {
        "EGRESO": {"ta": "102/62", "fc": "96", "fr": "20", "sat": "99", "temp": "36.8", "peso": "22", "talla": "118", "pc": "", "pb": "17"},
        "OBSERVACIÓN": {"ta": "96/58", "fc": "112", "fr": "24", "sat": "98", "temp": "37.4", "peso": "18", "talla": "108", "pc": "", "pb": "16"},
        "HOSPITALIZACIÓN": {"ta": "88/54", "fc": "132", "fr": "30", "sat": "95", "temp": "38.5", "peso": "16", "talla": "100", "pc": "", "pb": "15"},
    }
    preparados = {}
    for conducta, datos in escenarios.items():
        preparados[conducta] = {
            "motivo": datos["motivo"],
            "enfermedad": datos["enfermedad"],
            "estado": datos["estado"],
            "plan": datos["plan"],
            "justificacion": datos["justificacion"],
            "signos": datos.get("signos", signos_por_conducta[conducta]),
            "fecha_nacimiento": datos.get("fecha_nacimiento", date(2019, 5, 15)),
            "sexo": datos.get("sexo", "Femenino"),
            "examen_kwargs": datos.get("examen_kwargs", {}),
            "aiepi_estado": datos.get("aiepi_estado", "SE DOCUMENTAN ESTADO GENERAL, SIGNOS DE PELIGRO Y RESPUESTA CLÍNICA."),
            "aiepi_ingesta": datos.get("aiepi_ingesta", "SE DOCUMENTAN TOLERANCIA ORAL, HIDRATACIÓN Y DIURESIS SEGÚN CORRESPONDA."),
            "aiepi_control": datos.get("aiepi_control", "SE BRINDA INFORMACIÓN A PADRES O CUIDADOR RESPONSABLE SOBRE LA CONDUCTA, SIGNOS DE ALARMA Y RECONSULTA."),
        }
    _agregar_trio_urgencias(catalogo, familia, titulo, diagnostico, busqueda, preparados)


